 * RATE_CACHE_TTL_MS and reused for any parcel of the same zone and weight. Quotes asked for while
 * a request for the same zone and weight is still in flight share that request. A failed request
 * is not kept, so the next quote tries the carrier again.
 */
export function createRateQuoter(transport, now = Date.now) {
  const quotes = new Map();
  const inFlight = new Map();
  return function quoteRate(parcel) {
    const key = `${parcel.zone}:${parcel.weightGrams}`;
    const kept = quotes.get(key);
    if (kept !== undefined && now() - kept.quotedAt < RATE_CACHE_TTL_MS) {
      return Promise.resolve(kept.cents);
    }
    const pending = inFlight.get(key);
    if (pending !== undefined) return pending;
    const request = callCarrier(transport, 'rate', {
      zone: parcel.zone,
      weightGrams: parcel.weightGrams,
    })
      .then((answer) => {
        quotes.set(key, { cents: answer.cents, quotedAt: now() });
        return answer.cents;
      })
      .finally(() => inFlight.delete(key));
    inFlight.set(key, request);
    return request;
  };
}

