test('sends one request when the same parcel is quoted several times at once', async () => {
  const carrier = fakeCarrier();
  const quoteRate = createRateQuoter(carrier);
  const cents = await Promise.all([quoteRate(parcel), quoteRate(parcel), quoteRate(parcel)]);
  assert.deepEqual(cents, [650, 650, 650]);
  assert.equal(carrier.requests, 1);
});

test('sends a request for each different parcel quoted at once', async () => {
  const carrier = fakeCarrier();
  const quoteRate = createRateQuoter(carrier);
  await Promise.all([quoteRate(parcel), quoteRate({ ...parcel, weightGrams: 900 })]);
  assert.equal(carrier.requests, 2);
});

test('does not keep a failed request, so the next quote asks the carrier again', async () => {
  let fail = true;
  let requests = 0;
  const transport = {
    async send() {
      requests += 1;
      if (fail) throw new Error('carrier down');
      return { cents: 650 };
    },
  };
  const quoteRate = createRateQuoter(transport);
  await Promise.all([quoteRate(parcel), quoteRate(parcel)].map((q) => assert.rejects(q)));
  const failedRequests = requests;
  fail = false;
  assert.equal(await quoteRate(parcel), 650);
  assert.equal(requests, failedRequests + 1);
});

